import React, { useState, useEffect, useCallback } from 'react';
import './App.css';

function App() {
  const [currentPath, setCurrentPath] = useState('');
  const [folders, setFolders] = useState([]);
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState('');
  const [newFolderName, setNewFolderName] = useState('');
  const [selectedFiles, setSelectedFiles] = useState([]);

  const API_ENDPOINT = "https://6vkpjuest4.execute-api.eu-north-1.amazonaws.com/default/secure-upload-auth";

  const fetchDirectory = useCallback(async (path = '') => {
    setLoading(true);
    try {
      const response = await fetch(`${API_ENDPOINT}?prefix=${encodeURIComponent(path)}`);
      if (!response.ok) throw new Error("Failed to fetch directory contents.");
      const data = await response.json();
      setFolders(data.folders || []);
      setFiles(data.files || []);
    } catch (error) {
      console.error("Error fetching directory:", error);
      setMessage("Failed to load directory.");
    } finally {
      setLoading(false);
    }
  }, [API_ENDPOINT]);

  useEffect(() => {
    fetchDirectory(currentPath);
  }, [currentPath, fetchDirectory]);

  const handleFolderClick = (folderName) => {
    const nextPath = currentPath ? `${currentPath}/${folderName}` : folderName;
    setCurrentPath(nextPath);
  };

  const handleGoUp = () => {
    const parts = currentPath.split('/');
    parts.pop();
    setCurrentPath(parts.join('/'));
  };

  const handleCreateFolder = async (e) => {
    e.preventDefault();
    if (!newFolderName.trim()) return;

    const folderPath = currentPath ? `${currentPath}/${newFolderName.trim()}` : newFolderName.trim();
    try {
      const response = await fetch(API_ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: 'create_folder', folderPath }),
      });

      if (!response.ok) throw new Error("Failed to create folder.");
      setNewFolderName('');
      fetchDirectory(currentPath);
    } catch (error) {
      alert("Error creating folder: " + error.message);
    }
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!selectedFiles || selectedFiles.length === 0) {
      alert("Please select at least one file!");
      return;
    }

    setUploading(true);
    setMessage('Uploading files...');

    try {
      for (const file of selectedFiles) {
        // 1. Get presigned URL
        const res = await fetch(API_ENDPOINT, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            fileName: file.name,
            fileType: file.type,
            fileSize: file.size,
            folderPath: currentPath,
          }),
        });

        if (!res.ok) throw new Error(`Failed to authorize upload for ${file.name}`);
        const data = await res.json();

        // 2. Upload directly to S3
        const uploadRes = await fetch(data.uploadUrl, {
          method: "PUT",
          headers: { "Content-Type": file.type },
          body: file,
        });

        if (!uploadRes.ok) throw new Error(`Failed to upload ${file.name}`);
      }

      setMessage('Files uploaded successfully! 🎉');
      setSelectedFiles([]);
      fetchDirectory(currentPath);
    } catch (error) {
      console.error("Upload error:", error);
      setMessage('Upload failed: ' + error.message);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div style={{ padding: '30px', fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', maxWidth: '1000px', margin: 'auto' }}>
      <h2>🗂️ Secure File Explorer</h2>

      {/* Breadcrumb / Navigation Bar */}
      <div style={{ background: '#f5f5f5', padding: '12px 16px', borderRadius: '8px', marginBottom: '20px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div>
          <strong>Location: </strong>
          <code>/{currentPath}</code>
        </div>
        {currentPath && (
          <button onClick={handleGoUp} style={{ padding: '6px 12px', cursor: 'pointer' }}>
            ⬆️ Back
          </button>
        )}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '30px' }}>

        {/* Left Column: Actions (Create Folder & Upload Here) */}
        <div>
          <div style={{ background: '#fafafa', padding: '20px', borderRadius: '8px', border: '1px solid #ddd', marginBottom: '20px' }}>
            <h4>📁 Create Folder</h4>
            <form onSubmit={handleCreateFolder}>
              <input 
                type="text" 
                placeholder="Folder name" 
                value={newFolderName}
                onChange={(e) => setNewFolderName(e.target.value)}
                style={{ width: '100%', padding: '8px', marginBottom: '10px', boxSizing: 'border-box' }}
              />
              <button type="submit" style={{ width: '100%', padding: '8px', cursor: 'pointer' }}>Create</button>
            </form>
          </div>

          <div style={{ background: '#fafafa', padding: '20px', borderRadius: '8px', border: '1px solid #ddd' }}>
            <h4>📤 Upload Here</h4>
            <form onSubmit={handleUpload}>
              <input 
                type="file" 
                multiple 
                onChange={(e) => setSelectedFiles(e.target.files)}
                style={{ width: '100%', marginBottom: '15px' }} 
              />
              <button 
                type="submit" 
                disabled={uploading || selectedFiles.length === 0} 
                style={{ width: '100%', padding: '10px', cursor: 'pointer', background: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}
              >
                {uploading ? 'Uploading...' : 'Upload Files'}
              </button>
            </form>
            {message && <p style={{ marginTop: '10px', fontSize: '14px', fontWeight: 'bold' }}>{message}</p>}
          </div>
        </div>

        {/* Right Column: Finder View (Folders & Files) */}
        <div>
          <h3>Contents</h3>
          {loading ? (
            <p>Loading...</p>
          ) : (
            <div>
              {/* Folders List */}
              <div style={{ marginBottom: '20px' }}>
                <h5 style={{ color: '#666', borderBottom: '1px solid #eee', paddingBottom: '5px' }}>Folders</h5>
                {folders.length === 0 ? (
                  <p style={{ color: '#999', fontSize: '14px' }}>No subfolders</p>
                ) : (
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: '10px' }}>
                    {folders.map((folder) => (
                      <button
                        key={folder}
                        onClick={() => handleFolderClick(folder)}
                        style={{ padding: '12px', background: '#fff', border: '1px solid #ccc', borderRadius: '6px', cursor: 'pointer', textAlign: 'left', fontWeight: '500' }}
                      >
                        📁 {folder}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Files List */}
              <div>
                <h5 style={{ color: '#666', borderBottom: '1px solid #eee', paddingBottom: '5px' }}>Files</h5>
                {files.length === 0 ? (
                  <p style={{ color: '#999', fontSize: '14px' }}>No files in this folder</p>
                ) : (
                  <ul style={{ listStyle: 'none', padding: 0 }}>
                    {files.map((file) => (
                      <li key={file.name} style={{ background: '#fff', border: '1px solid #eee', padding: '10px 14px', marginBottom: '8px', borderRadius: '6px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <span>📄 {file.name}</span>
                        <span style={{ color: '#888', fontSize: '13px' }}>{(file.size / (1024*1024)).toFixed(2)} MB</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

export default App;
